'use strict';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],E=NavEngine;
const read=k=>{try{return JSON.parse(localStorage.getItem(k)||'[]')}catch{return []}},write=(k,v)=>{try{localStorage.setItem(k,JSON.stringify(v));return true}catch{toast('브라우저 저장 공간에 접근할 수 없어요.');return false}};
let graph,map,origin=[37.5960634,127.0384638],originName='학교 앞 정류장 부근 · 시연 출발점',destination=null,profile,analyzed='',routes=[],selected=0,watchId=null,currentStep=-1,detailGroups=[],toastTimer,pickMode=null,gpsMarker,accuracyCircle;
let journeyStages=[],activeStage=0;
const stageMarkers=L.layerGroup(),stageFocus=L.layerGroup();
const pins={},routeLayer=L.layerGroup(),benchLayer=L.layerGroup(),snapLayer=L.layerGroup();
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4000)}
function textEl(tag,text,className){const e=document.createElement(tag);e.textContent=text;if(className)e.className=className;return e}
function icon(type,text){return L.divIcon({className:'map-pin '+type,html:`<span>${text}</span>`,iconSize:[30,30],iconAnchor:[15,15]})}
function placePin(type,ll,title){if(pins[type])pins[type].remove();pins[type]=L.marker(ll,{icon:icon(type,type==='origin'?'출':'도'),draggable:true,autoPan:true,title}).addTo(map).bindTooltip(title,{direction:'top'});pins[type].on('dragend',()=>{const p=pins[type].getLatLng(),ll=[p.lat,p.lng];if(type==='origin')setOrigin(ll,'지도에서 지정한 출발지');else setDestination({ll,name:'지도에서 지정한 목적지'})})}
function invalidate(message='조건이 바뀌었어요. 길 찾기를 눌러 다시 계산해 주세요.'){if(routes.length){routes=[];routeLayer.clearLayers();snapLayer.clearLayers();$('#routes').replaceChildren(textEl('p',message,'empty-note'));$('#result-title').textContent='다시 길 찾기'}clearOrder();stopTracking(false)}
function setOrigin(ll,name){origin=ll;originName=name;$('#origin-name').textContent=name;placePin('origin',ll,name);invalidate();$('#location-status').textContent='실제 출입구와 보행로를 확인해 출발 핀을 조정할 수 있어요.'}
function setDestination(place){destination=place;$('#destination-query').value=place.name;$('#destination-status').textContent='선택됨 · '+place.name;$('#places').replaceChildren();placePin('destination',place.ll,place.name);invalidate();map.panTo(place.ll)}
function analyze(){profile=E.parseState($('#condition').value);analyzed=$('#condition').value;$('#stairs').checked=profile.avoidSteps;$('#slope').checked=profile.avoidSlope;$('#rest').checked=profile.rest;$('#short').checked=profile.short;$('#stairs').disabled=profile.wheelchair;$('#parser-note').textContent=(profile.recognized?'이동 조건을 해석했어요. 아래 항목을 수정할 수 있어요.':'알려진 이동 조건을 찾지 못했어요. 아래 조건을 직접 선택해 주세요.')+' · 기기 내 문장 규칙 사용'+(profile.restMinutes?` · ${profile.restMinutes}분 휴식 간격 요청`:'');invalidate();return profile}
function effectiveProfile(){if(analyzed!==$('#condition').value)analyze();return {...profile,avoidSteps:$('#stairs').checked||profile.wheelchair,avoidSlope:$('#slope').checked,rest:$('#rest').checked,short:$('#short').checked}}
$('#analyze').onclick=()=>{analyze();toast('문장에서 이동 조건을 확인했어요.')};$$('[data-example]').forEach(b=>b.onclick=()=>{$('#condition').value=b.dataset.example;analyze()});$('#condition').oninput=()=>{invalidate();$('#parser-note').textContent='상태가 바뀌었어요. 조건 확인 또는 길 찾기를 눌러 주세요.'};$$('.condition-chips input').forEach(i=>i.onchange=()=>invalidate());
function searchPlaces(){if(!graph)return;const q=$('#destination-query').value.trim().toLowerCase(),items=graph.places.filter(p=>E.distance(E.school,p.ll)<1800&&(!q||p.name.toLowerCase().includes(q))).slice(0,12);$('#places').replaceChildren();items.forEach(p=>{const b=textEl('button',p.name);b.type='button';b.append(textEl('small',`${Math.round(E.distance(origin,p.ll))}m 직선거리 · ${({cafe:'카페',library:'도서관',school:'학교',bus_stop:'정류장'})[p.type]||'장소'}`));b.onclick=()=>setDestination(p);$('#places').append(b)});if(!items.length)$('#places').append(textEl('p','등록된 주변 장소가 없어요. 지도에서 목적지를 선택해 주세요.','empty-note'))}
$('#destination-query').oninput=()=>{destination=null;invalidate();$('#destination-status').textContent='검색 결과에서 목적지를 선택해 주세요.';searchPlaces()};$('#destination-query').onfocus=searchPlaces;
function chooseOnMap(mode){pickMode=mode;$('#map-instruction').hidden=false;$('#map-instruction').textContent=(mode==='origin'?'출발':'도착')+'할 보행로를 지도에서 눌러 주세요. 같은 버튼을 다시 누르면 취소돼요.';$('#live-map').scrollIntoView({behavior:'smooth',block:'center'});map.invalidateSize()}
$('#pick-origin').onclick=()=>{if(pickMode==='origin'){pickMode=null;$('#map-instruction').hidden=true}else chooseOnMap('origin')};$('#pick-destination').onclick=()=>{if(pickMode==='destination'){pickMode=null;$('#map-instruction').hidden=true}else chooseOnMap('destination')};
function getPosition(){if(!navigator.geolocation){toast('이 브라우저는 위치 기능을 지원하지 않아요. 지도에서 출발지를 선택해 주세요.');return}$('#locate').disabled=true;$('#location-status').textContent='위치 권한을 허용해 주세요. 현재 위치를 확인하고 있어요…';navigator.geolocation.getCurrentPosition(pos=>{$('#locate').disabled=false;const ll=[pos.coords.latitude,pos.coords.longitude];setOrigin(ll,'현재 위치 · GPS');$('#location-status').textContent=`GPS 정확도 약 ${Math.round(pos.coords.accuracy)}m${pos.coords.accuracy>80?' · 오차가 커요. 출발 핀을 보정해 주세요.':''}`;if(accuracyCircle)accuracyCircle.remove();accuracyCircle=L.circle(ll,{radius:pos.coords.accuracy,color:'#4b8aba',weight:1,fillOpacity:.08}).addTo(map);map.setView(ll,17);if(E.distance(ll,E.school)>2000)toast('현재 위치가 학교 시연 범위 밖입니다. 학교 주변 시연 버튼이나 지도에서 출발지를 지정해 주세요.')},err=>{$('#locate').disabled=false;$('#location-status').textContent=err.code===1?'위치 권한이 거부됐어요. 브라우저 설정에서 허용하거나 지도에서 출발지를 지정해 주세요.':'위치를 확인하지 못했어요. 실외에서 다시 시도하거나 지도에서 출발지를 지정해 주세요.'},{enableHighAccuracy:true,timeout:15000,maximumAge:10000})}
$('#locate').onclick=getPosition;
$('#school-reset').onclick=()=>{if(!graph)return;setOrigin([37.5960634,127.0384638],'학교 앞 정류장 부근 · 시연 출발점');$('#location-status').textContent='GPS 위치가 아닌 시연 출발점입니다. 현재 위치 사용으로 전환할 수 있어요.';setDestination(graph.places.find(p=>p.name==='종월2교')||graph.places.find(p=>p.type==='cafe'));map.setView(E.school,16);toast('학교 주변 시연 위치로 이동했어요.')};
$('#search').onsubmit=async ev=>{ev.preventDefault();if(!graph)return;if(!destination){toast('검색 결과에서 목적지를 선택하거나 지도를 눌러 주세요.');return}if(E.distance(origin,E.school)>2300||E.distance(destination.ll,E.school)>2300){$('#search-status').textContent='학교 주변 약 2km 밖은 현재 경로 데이터가 없어요. 학교 주변 시연을 선택해 주세요.';return}const p=effectiveProfile();$('#find-route').disabled=true;$('#search-status').textContent='실제 도로 그래프에서 이동 조건에 맞는 경로를 계산하고 있어요…';await new Promise(requestAnimationFrame);try{const fitted=E.route(graph,origin,destination.ll,p);routes=[{...fitted,label:p.rest?'벤치를 경유하는 맞춤 경로':'내 상태를 반영한 경로',p}];const basic=E.route(graph,origin,destination.ll,{speed:p.speed,short:true});if(basic.ids.join(',')!==fitted.ids.join(','))routes.push({...basic,label:'일반 최단 경로 · 비교용',p:{...p,avoidSteps:false,avoidSlope:false,rest:false,short:true},comparison:true});selected=0;renderRoutes();drawRoutes(true);$('#search-status').textContent=p.rest?(fitted.restStop?'OSM에 등록된 벤치를 실제 경유지로 반영했어요. 시설 상태는 현장에서 확인해 주세요.':'휴식 조건을 만족하는 경유지를 찾지 못했어요. 결과의 제한 사항을 확인해 주세요.'):(routes.length===1?'현재 데이터에서는 맞춤 경로와 일반 최단 경로가 같아요.':'이동 조건을 적용해 일반 최단 경로와 비교했어요.');$('#result-title').textContent='실제 도로 경로 '+routes.length+'개';$('#route-order').scrollIntoView({behavior:'smooth',block:'start'})}catch(e){routes=[];routeLayer.clearLayers();snapLayer.clearLayers();$('#routes').replaceChildren();clearOrder();$('#search-status').textContent=e.message}finally{$('#find-route').disabled=false}};
function renderRoutes(){const c=$('#routes');c.replaceChildren();routes.forEach((r,i)=>{const card=textEl('article','','route-card'+(selected===i?' selected':''));const choose=textEl('button','');choose.type='button';choose.style.cssText='border:0;background:transparent;padding:0;width:100%;text-align:left';choose.setAttribute('aria-pressed',selected===i);choose.setAttribute('aria-label',r.label);const top=textEl('div','','route-header');top.append(textEl('span',r.label,'route-tag'+(r.comparison?' tag-gray':'')),textEl('span','','select-circle'));const time=textEl('div',r.minutes+'분','route-time');time.append(textEl('em',Math.round(r.length)+'m · 보행 속도에 따른 추정'));const stairs=r.edges.filter(e=>e.steps).reduce((a,e)=>a+e.d,0),features=textEl('div','','route-features');features.append(textEl('span','계단 '+(stairs?Math.round(stairs)+'m':'등록 구간 없음')),textEl('span','경사 미확인 '+Math.round(r.unknown)+'m'));choose.append(top,time,features);if(r.restStop)choose.append(textEl('p',`☕ 등록 벤치 경유 · 첫 휴식까지 약 ${Math.ceil(r.restStop.firstDistance/r.p.speed)}분 · 벤치 연결 ${Math.round(r.restStop.gap)}m 미검증`,'route-description'));choose.onclick=()=>{selected=i;renderRoutes();drawRoutes(true)};card.append(choose);if(r.comparison)card.append(textEl('p','입력한 이동 제약을 적용하지 않은 비교 경로입니다.','route-status'));const warns=textEl('div',r.messages.join(' '),'route-warnings');card.append(warns);card.append(textEl('p',`출발점→도로 약 ${Math.round(r.gaps[0])}m / 도로→목적지 약 ${Math.round(r.gaps[1])}m는 미검증 연결입니다. 표시 거리는 도로 구간만 포함합니다.`,'gap-note'));if(selected===i){const go=textEl('button','구간 자세히 보기 →','route-go');go.onclick=showDetails;card.append(go)}c.append(card)})}
function drawRoutes(fit){routeLayer.clearLayers();snapLayer.clearLayers();routes.forEach((r,i)=>{if(i===selected)return;L.polyline(r.coords,{color:'#8d9895',weight:5,opacity:.8,dashArray:'7 8'}).addTo(routeLayer)});const r=routes[selected];if(!r)return;L.polyline(r.coords,{color:'white',weight:12,opacity:.95}).addTo(routeLayer);L.polyline(r.coords,{color:'#176d52',weight:7,opacity:.95}).addTo(routeLayer);[[origin,r.from],[r.to,destination.ll]].forEach(coords=>L.polyline(coords,{color:'#cc9344',weight:3,dashArray:'4 6'}).bindTooltip('도로까지 미검증 연결 · 현장에서 확인').addTo(snapLayer));if(r.restStop)L.polyline([r.restStop.snap,r.restStop.ll],{color:'#cc9344',weight:3,dashArray:'4 6'}).addTo(snapLayer);if(r.restStop)L.marker(r.restStop.ll,{icon:L.divIcon({className:'bench-pin',html:'<span>☕</span>',iconSize:[25,25]})}).addTo(routeLayer).bindPopup('OSM 등록 벤치 · 현장 미검증');if(fit)map.fitBounds(L.latLngBounds([...r.coords,origin,destination.ll]),{padding:[45,90],maxZoom:18});buildOrder(r)}
$('#fit-route').onclick=()=>{if(routes.length)drawRoutes(true);else map.setView(E.school,16);if(innerWidth<=700)$('#live-map').scrollIntoView({behavior:'smooth',block:'center'})};

function clearOrder(){journeyStages=[];stageMarkers.clearLayers();stageFocus.clearLayers();$('#route-order').hidden=true;$('#order-list').replaceChildren()}
function bearing(a,b){return Math.atan2((b[1]-a[1])*Math.cos(a[0]*Math.PI/180),b[0]-a[0])*180/Math.PI}
function turnLabel(previous,coords){if(!previous||previous.length<2||coords.length<2)return '→';const delta=(bearing(coords[0],coords[1])-bearing(previous.at(-2),previous.at(-1))+540)%360-180;return Math.abs(delta)>150?'↶':delta>35?'↱':delta< -35?'↰':'↑'}
function buildOrder(r){clearOrder();const groups=[];let previous=null;for(let i=0;i<r.edges.length;i++){const e=r.edges[i],last=groups.at(-1);if(last&&!last.bench&&last.name===e.name&&last.steps===e.steps){last.length+=e.d;last.coords.push(r.coords[i+1])}else{const coords=[r.coords[i],r.coords[i+1]],arrow=turnLabel(previous,coords);groups.push({name:e.name,length:e.d,coords,steps:e.steps,arrow})}previous=[r.coords[i],r.coords[i+1]];if(r.restStop&&E.distance(r.coords[i+1],r.restStop.snap)<1&&!groups.some(g=>g.bench))groups.push({name:'등록 벤치에서 쉬어가기',bench:true,coords:[r.restStop.snap,r.restStop.ll],length:0,gap:r.restStop.gap})}
journeyStages=[{title:'출발 · '+originName,sub:`보행로까지 약 ${Math.round(r.gaps[0])}m · 연결은 현장에서 확인`,coords:[origin,r.from],kind:'start',arrow:'출'},...groups.map(g=>({...g,title:g.bench?g.name:`${g.name} 따라 ${Math.round(g.length)}m 이동`,sub:g.bench?`보행로에서 약 ${Math.round(g.gap)}m · 벤치 상태 미확인`:g.steps?'계단 구간 · 주의해서 확인하세요.':`${g.arrow==='↱'?'오른쪽으로 방향 전환':g.arrow==='↰'?'왼쪽으로 방향 전환':g.arrow==='↶'?'반대 방향으로 전환':'길을 따라 이어서 이동'} · 지도 기준 안내`,kind:g.bench?'rest':'walk',arrow:g.bench?'☕':g.arrow})),{title:'도착 · '+destination.name,sub:`도로에서 목적지까지 약 ${Math.round(r.gaps[1])}m · 출입구는 현장 확인`,coords:[r.to,destination.ll],kind:'finish',arrow:'도'}];activeStage=0;$('#route-order').hidden=false;renderOrder();journeyStages.forEach((stage,i)=>{if(stage.kind==='start'||stage.kind==='finish')return;const ll=stage.kind==='rest'?stage.coords.at(-1):stage.coords[Math.floor(stage.coords.length/2)],marker=L.marker(ll,{icon:L.divIcon({className:'order-map-marker'+(stage.kind==='rest'?' rest-marker':''),html:`<span>${i+1}</span>`,iconSize:[25,25],iconAnchor:[12,12]}),title:`${i+1}. ${stage.title}`,keyboard:true}).addTo(stageMarkers);marker.bindTooltip(`${i+1}. ${stage.title}`);marker.on('click',()=>selectStage(i,true))})}
function renderOrder(){const c=$('#order-list');c.replaceChildren();journeyStages.forEach((stage,i)=>{const li=document.createElement('li'),button=textEl('button','','order-step'+(i===activeStage?' is-current':'')+(stage.kind==='rest'?' is-rest':''));button.type='button';if(i===activeStage)button.setAttribute('aria-current','step');button.setAttribute('aria-label',`${i+1}단계. ${stage.title}. ${stage.sub}`);const number=textEl('span',String(i+1),'order-number'),body=textEl('span','','order-step-body');body.append(textEl('b',stage.title),textEl('small',stage.sub));button.append(number,body,textEl('span',stage.arrow,'order-arrow'));button.onclick=()=>selectStage(i,true);li.append(button);c.append(li)});$('#order-progress').textContent=`${activeStage+1} / ${journeyStages.length} 단계`;$('#order-prev').disabled=activeStage===0;$('#order-next').disabled=activeStage===journeyStages.length-1;$('#order-next').textContent=activeStage===journeyStages.length-2?'도착 지점 보기 →':'다음 구간 →';const row=c.children[activeStage];if(row){const rb=row.getBoundingClientRect(),cb=c.getBoundingClientRect();if(rb.top<cb.top)c.scrollTop-=cb.top-rb.top;else if(rb.bottom>cb.bottom)c.scrollTop+=rb.bottom-cb.bottom}}
function selectStage(index,fit){if(index<0||index>=journeyStages.length)return;activeStage=index;renderOrder();stageFocus.clearLayers();const stage=journeyStages[index];L.polyline(stage.coords,{color:'#fff',weight:17,opacity:1}).addTo(stageFocus);L.polyline(stage.coords,{color:'#e09a36',weight:9,opacity:1}).addTo(stageFocus);L.circleMarker(stage.coords.at(-1),{color:'white',weight:3,radius:9,fillColor:'#d18a27',fillOpacity:1}).addTo(stageFocus);if(fit)map.fitBounds(L.latLngBounds(stage.coords),{padding:[70,120],maxZoom:18});if(innerWidth<=700)$('#live-map').scrollIntoView({behavior:'smooth',block:'center'})}
$('#order-prev').onclick=()=>selectStage(activeStage-1,true);$('#order-next').onclick=()=>selectStage(activeStage+1,true);

function groupSteps(r){const groups=[];for(const e of r.edges){const last=groups.at(-1);if(last&&last.id===e.id)last.length+=e.d;else groups.push({id:e.id,name:e.name,length:e.d,steps:e.steps,incline:e.incline});if(r.restStop&&E.distance(graph.nodes.get(e.to).ll,r.restStop.snap)<1&&!groups.some(x=>x.bench))groups.push({id:'bench',name:'등록 벤치에서 쉬어가기',length:0,bench:true,gap:r.restStop.gap})}return groups}
function showDetails(){const r=routes[selected];if(!r)return;currentStep=-1;detailGroups=groupSteps(r);$('#detail-title').textContent=r.label;$('#detail-summary').textContent=`${originName} → ${destination.name} · 약 ${r.minutes}분 / ${Math.round(r.length)}m`;$('#detail-dialog .demo-banner').textContent='실제 공개 도로 기반 · 미검증 연결 구간과 시설 상태를 확인하세요. 시뮬레이션과 GPS 안내를 선택할 수 있어요.';renderSteps();$('#next-step').textContent='시뮬레이션 시작 →';if(!$('#start-live')){const wrap=textEl('div','','detail-mode'),live=textEl('button','◎ GPS로 이동 확인','secondary');live.id='start-live';live.onclick=startTracking;wrap.append(live);$('#detail-dialog').append(wrap)}$('#detail-dialog').showModal()}
function renderSteps(){const c=$('#steps');c.replaceChildren();detailGroups.forEach((s,i)=>{const li=textEl('li',s.bench?s.name:s.name+' 따라 약 '+Math.round(s.length)+'m',currentStep===i?'current':'');li.append(textEl('small',s.bench?`보행로에서 벤치까지 약 ${Math.round(s.gap)}m · 연결과 시설 상태 미확인`:s.steps?'계단 구간 · 비교 경로 이용 주의':s.incline===null?'경사 정보 미확인':'OSM 등록 경사 '+s.incline+'%'));c.append(li)})}
$('#next-step').onclick=()=>{currentStep++;if(currentStep>=detailGroups.length){currentStep=-1;$('#next-step').textContent='다시 체험하기 ↻';toast('시뮬레이션을 완료했어요. 실제 도착 여부를 확인한 것은 아닙니다.')}else $('#next-step').textContent=currentStep===detailGroups.length-1?'시뮬레이션 완료 ✓':'다음 구간 →';renderSteps();$('#steps .current')?.scrollIntoView({block:'nearest'})};
function stopTracking(notify=true){if(watchId!==null)navigator.geolocation.clearWatch(watchId);watchId=null;$('#live-guidance').hidden=true;if(notify)toast('GPS 이동 확인을 종료했어요.')}
function startTracking(){if(!navigator.geolocation)return toast('브라우저가 위치 기능을 지원하지 않아요.');const r=routes[selected];if(!r)return;stopTracking(false);$('#detail-dialog').close();$('#live-guidance').hidden=false;$('#live-guidance').textContent='GPS 위치를 확인하고 있어요…';$('#live-map').scrollIntoView({behavior:'smooth',block:'center'});watchId=navigator.geolocation.watchPosition(pos=>{const ll=[pos.coords.latitude,pos.coords.longitude];if(gpsMarker)gpsMarker.remove();gpsMarker=L.circleMarker(ll,{radius:8,color:'white',weight:3,fillColor:'#438dc6',fillOpacity:1}).addTo(map);let best=Infinity,index=0;r.coords.forEach((c,i)=>{const d=E.distance(c,ll);if(d<best){best=d;index=i}});const remaining=r.edges.slice(index).reduce((s,e)=>s+e.d,0);const c=$('#live-guidance');c.replaceChildren(textEl('b',`GPS 정확도 ±${Math.round(pos.coords.accuracy)}m`),textEl('div',best>70?`경로에서 약 ${Math.round(best)}m 떨어져 있어요. 출발 위치를 확인해 주세요.`:`도로상 남은 거리 약 ${Math.round(remaining)}m · ${r.edges[index]?.name||'목적지 인근'}`),textEl('small','자동 재탐색·정확한 회전 안내는 지원하지 않아요.'));const stop=textEl('button','위치 확인 종료');stop.onclick=()=>stopTracking();c.append(stop)},err=>{stopTracking(false);toast(err.code===1?'위치 권한이 거부됐어요. 시뮬레이션을 이용할 수 있어요.':'GPS 위치를 받지 못했어요. 다시 시도해 주세요.')},{enableHighAccuracy:true,timeout:15000,maximumAge:5000})}
$('#save-route').onclick=()=>{const r=routes[selected];if(!r)return;const item={id:Date.now(),origin,originName,destination,condition:$('#condition').value,options:r.p,label:r.label};if(write('donghaeng.school.routes',[item,...read('donghaeng.school.routes')]))toast('이 브라우저에 경로 조건을 저장했어요.')};
$$('[data-view]').forEach(b=>b.onclick=()=>{$$('[data-view]').forEach(x=>x.classList.toggle('active',x===b));$('#planner').hidden=b.dataset.view!=='route';$('#saved-view').hidden=b.dataset.view!=='saved';$('.intro').hidden=b.dataset.view==='saved';if(b.dataset.view==='saved')renderSaved()});
function renderSaved(){const c=$('#saved-list'),items=read('donghaeng.school.routes');c.replaceChildren();if(!items.length)c.append(textEl('p','경로 상세에서 저장하면 여기에 나타나요.','empty-note'));items.forEach(item=>{const box=textEl('div','','saved-item');box.append(textEl('b',item.destination.name),textEl('p',item.condition));const open=textEl('button','이 조건으로 다시 찾기 →');open.onclick=()=>{setOrigin(item.origin,item.originName);setDestination(item.destination);$('#condition').value=item.condition;analyze();$('#stairs').checked=item.options.avoidSteps;$('#slope').checked=item.options.avoidSlope;$('#rest').checked=item.options.rest;$('#short').checked=item.options.short;$('[data-view="route"]').click();$('#search').requestSubmit()};const del=textEl('button','삭제');del.onclick=()=>{if(write('donghaeng.school.routes',items.filter(x=>x.id!==item.id)))renderSaved()};box.append(open,del);c.append(box)})}
function info(title,text){$('#info-title').textContent=title;$('#info-text').textContent=text;$('#info-dialog').showModal()}
$('#about').onclick=()=>info('학교에서 직접 시연해 보세요','① 현재 위치 사용을 누르고 권한을 허용하세요. ② 학교 주변 목적지를 검색 결과에서 고르거나 지도에서 선택하세요. ③ 몸 상태를 입력하고 길 찾기를 누르세요. 문장은 이 기기의 규칙으로 해석하며 외부 AI에 보내지 않습니다. 실제 OSM 도로 그래프를 탐색하고, 등록 계단 제외·경사 부담 가중치·등록 벤치 경유를 적용합니다. 지도 타일은 OpenStreetMap 서버에서 받습니다. 위치와 상태는 서버에 저장하지 않으며 경로/제보 저장은 이 브라우저에만 적용됩니다. 학교 주변 데이터만 포함되어 있고 보도 턱·폭·출입구·경사 대부분은 미확인입니다. 교내 길 안내와 접근성 보장은 지원하지 않습니다.');
$('#report-open').onclick=()=>{$('#report-place').value=destination?.name||originName;renderReports();$('#report-dialog').showModal()};$('#report-form').onsubmit=e=>{e.preventDefault();const p=$('#report-place').value.trim(),t=$('#report-text').value.trim();if(!p||!t)return toast('위치와 상세 내용을 입력해 주세요.');if(write('donghaeng.school.reports',[{place:p,text:t,type:$('#report-type').value,date:new Date().toLocaleDateString('ko-KR')},...read('donghaeng.school.reports')])){$('#report-form').reset();renderReports();toast('제보를 이 브라우저에 저장했어요. 경로에 자동 반영되지는 않습니다.')}};
function renderReports(){const c=$('#report-history'),items=read('donghaeng.school.reports');c.replaceChildren();if(items.length)c.append(textEl('b','내 제보 '+items.length+'건'));items.slice(0,5).forEach(x=>c.append(textEl('p',`${x.type} · ${x.place} / ${x.text}`)))}
$$('dialog .close').forEach(b=>b.onclick=()=>b.closest('dialog').close());document.addEventListener('click',e=>{if(!e.target.closest('.destination-field'))$('#places').replaceChildren()});window.addEventListener('pagehide',()=>stopTracking(false));
async function init(){try{map=L.map('live-map',{zoomControl:false}).setView(E.school,16);L.control.zoom({position:'topright'}).addTo(map);L.control.scale({imperial:false,position:'bottomleft'}).addTo(map);L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap contributors</a>'}).on('tileerror',()=>{$('#data-note').textContent='배경 지도 연결이 원활하지 않아요. 포함된 공개 도로망으로 경로를 확인할 수 있습니다. 시설·접근성은 현장 미검증입니다.'}).addTo(map);routeLayer.addTo(map);snapLayer.addTo(map);benchLayer.addTo(map);stageMarkers.addTo(map);stageFocus.addTo(map);const response=await fetch('map-data.json');if(!response.ok)throw Error('도로 데이터 로딩 실패');graph=E.createGraph(await response.json());const renderer=L.canvas({padding:.3});graph.ways.forEach(w=>{const pts=w.nodes.map(id=>graph.nodes.get(id)?.ll).filter(Boolean);if(pts.length>1)L.polyline(pts,{renderer,color:w.meta.steps?'#c59b66':'#8eaa96',weight:w.meta.steps?2:1,opacity:.24,interactive:false}).addTo(map)});routeLayer.bringToFront?.();graph.benches.forEach(b=>{L.circleMarker(b.ll,{radius:4,color:'#72965b',weight:1,fillColor:'#edf4e3',fillOpacity:1}).addTo(benchLayer).bindPopup('OSM 등록 벤치 · 실제 운영 상태 미확인')});map.on('click',ev=>{if(!pickMode)return;const ll=[ev.latlng.lat,ev.latlng.lng];if(E.distance(ll,E.school)>2300)return toast('학교 주변 약 2km 안에서 선택해 주세요.');if(pickMode==='origin')setOrigin(ll,'지도에서 지정한 출발지');else setDestination({ll,name:'지도에서 지정한 목적지'});pickMode=null;$('#map-instruction').hidden=true});setOrigin(origin,originName);$('#location-status').textContent='현재 GPS가 아닌 시연 출발점입니다. 현재 위치 사용을 눌러 주세요.';setDestination(graph.places.find(p=>p.name==='종월2교')||graph.places.find(p=>p.type==='cafe'));$('#find-route').disabled=false;analyze();$('#data-note').textContent=`OSM 도로 데이터 ${graph.meta.timestamp?.slice(0,10)||'조회 시점'} 기준 · 계단/경사/벤치 등록 정보만 사용합니다. 미등록 시설·보도 턱·폭·출입구는 현장 확인이 필요합니다.`;$('#search-status').textContent='학교 주변 데이터 준비 완료. 현재 위치를 사용하거나 시연 출발점에서 바로 길 찾기를 눌러 보세요.';}catch(e){$('#search-status').textContent='지도 준비 실패: '+e.message+' · 새로고침으로 다시 시도해 주세요.';$('#destination-status').textContent='데이터를 불러오지 못했어요.'}}
init();
